// =====================================================================
// Envia as fotos do pedido pelo BotConversa.
// Entrada: o JSON que a Edge Function do FotoBarco manda (ver
// supabase/functions/_shared/whatsapp.ts).
// =====================================================================

// >>> PREENCHER: BotConversa > Configuracoes > Integracoes > API (API-KEY)
const API_KEY = 'COLE_AQUI_A_API_KEY_DO_BOTCONVERSA';

const BASE = 'https://backend.botconversa.com.br/api/v1/webhook';
// Pausa entre mensagens: rajada de muitas midias seguidas aumenta o risco
// de o WhatsApp bloquear o numero.
const PAUSA_MS = 1500;

const pedido = $('Pedido pago (Supabase)').first().json.body;
const headers = { 'API-KEY': API_KEY, 'Content-Type': 'application/json' };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const http = (opts) => this.helpers.httpRequest({ json: true, headers, ...opts });

// ------------------------------------------- 1. achar ou criar o contato --
let subscriber = null;
try {
  subscriber = await http({ method: 'GET', url: `${BASE}/subscriber/get_by_phone/${pedido.phone}/` });
} catch (e) {
  // 404 = contato ainda nao existe no BotConversa.
}

if (!subscriber?.id) {
  subscriber = await http({
    method: 'POST',
    url: `${BASE}/subscriber/`,
    body: {
      phone: `+${pedido.phone}`,
      first_name: 'Cliente',
      last_name: 'Jangalancha',
      // O cliente digitou o proprio numero no tablet pedindo as fotos.
      has_opt_in_whatsapp: true,
    },
  });
}

const send = (type, value) => http({
  method: 'POST',
  url: `${BASE}/subscriber/${subscriber.id}/send_message/`,
  body: { type, value },
});

// ------------------------------------------------------ 2. as mensagens --
const qtd = pedido.photoCount;
await send('text',
  `Ola! 🐬 Obrigado por passear com a Jangalancha Show!\n\n` +
  `Aqui estao suas ${qtd} foto${qtd === 1 ? '' : 's'}` +
  (pedido.session ? ` do ${pedido.session}` : '') + '. 📸');
await sleep(PAUSA_MS);

let enviadas = 0;
const falhas = [];
for (const foto of pedido.photos) {
  try {
    await send('file', foto.url);
    enviadas++;
  } catch (e) {
    falhas.push({ id: foto.id, erro: String(e.message || e).slice(0, 200) });
  }
  await sleep(PAUSA_MS);
}

await send('text', 'Esperamos que tenha gostado! Volte sempre. 🌊');

return [{ json: { orderId: pedido.orderId, subscriberId: subscriber.id, enviadas, falhas } }];
